        self.email = email
        self.address = address
        self.credit_card = credit_card

class Purchase:
    def __init__(self, id, client, items, total, payment_method):
        self.id = id
        self.client = client
        self.items = items
        self.total = total
        self.payment_method = payment_method

purchases = {
    "ORD002": Purchase("ORD002", 
                       User("John Smith", "john.smith@example.com", "456 Park Ave, Metropolis, USA", "9876-5432-1098-7654"),
                       ["Item A", "Item B"],
                       150.50,
                       "Credit Card")
}

def create_user_receipt(order_id, template):
    if order_id not in purchases:
        raise ValueError("Order not found")
    purchase = purchases[order_id]
    class SecurePurchase:
        def __init__(self, purchase):
            self._purchase = purchase

        def __getattr__(self, name):
            if name == 'client':
                return SecureUser(self._purchase.client)
            return getattr(self._purchase, name)

    class SecureUser:
        def __init__(self, client):
            self._client = client

        def __getattr__(self, name):
            if name in ['address', 'credit_card']:
                raise ValueError(f"Access to {name} is not allowed in receipts")
            return getattr(self._client, name)

    secure_purchase = SecurePurchase(purchase)
    return template.format(order=secure_purchase, customer=secure_purchase.client)

