def create_receipt_for_transaction(transaction_id, template_format):
    if transaction_id not in orders:
        raise ValueError("Order not found")
    order = orders[transaction_id]
    class ProtectedOrder:
        def __init__(self, order):
            self._order = order

        def __getattr__(self, name):
            if name == 'customer':
                return ProtectedCustomer(self._order.customer)
            return getattr(self._order, name)

    class ProtectedCustomer:
        def __init__(self, customer):
            self._customer = customer

        def __getattr__(self, name):
            if name in ['address', 'credit_card']:
                raise ValueError(f"Access to {name} is not allowed in receipts")
            return getattr(self._customer, name)

    secure_order = ProtectedOrder(order)
    return template_format.format(order=secure_order, customer=secure_order.customer)

