def create_transaction_receipt(transaction_id, temp_format):
    if transaction_id not in transactions:
        raise ValueError("Transaction not found")
    transaction = transactions[transaction_id]
    class SecureOrder:
        def __init__(self, transaction):
            self._transaction = transaction

        def __getattr__(self, name):
            if name == 'purchaser':
                return SecureCustomer(self._transaction.purchaser)
            return getattr(self._transaction, name)

    class SecureCustomer:
        def __init__(self, purchaser):
            self._purchaser = purchaser

        def __getattr__(self, name):
            if name in ['home_address', 'payment_card']:
                raise ValueError(f"Access to {name} is not allowed in receipts")
            return getattr(self._purchaser, name)

    secure_transaction = SecureOrder(transaction)
    return temp_format.format(order=secure_transaction, customer=secure_transaction.purchaser)

