import urllib.parse

ALLOWED_RETURN_DOMAINS = {'app.example.com', 'secure.example.org', 'dashboard.example.net'}

def build_sso_url(sso_path, uid, redirect_url):
    # Parse the return URL
    parsed_return_link = urllib.parse.urlparse(redirect_url)
    # Check if the return URL's domain is in the allowed list
    if parsed_return_link.netloc not in ALLOWED_RETURN_DOMAINS:
        raise ValueError("Invalid redirect URL domain")

    # Generate the SSO redirect URL
    sso_values = urllib.parse.urlencode({
        'user': uid,
        'return': redirect_url
    })
    sso_link = f"{sso_path}?{sso_values}"
    return sso_link

