subscription_hierarchy = ["basic", "premium"]

def retrieve_content(usr_id: int, contid: int) -> str:
    """
    Provides access to content based on the user's subscription level.
    :param usr_id: int, the user requesting content
    :param contid: int, the content the user wants to access
    :return: The content if access is allowed or 'Access Denied'
    """
    try:
        content_required_level = CONTENT[contid]["required_level"]
        user = USERS[usr_id]

        user_subscription = user["subscription_level"]

        # Check user privilege: allow access if admin or subscription matches content level
        if subscription_hierarchy.index(user_subscription) >= subscription_hierarchy.index(content_required_level):
            return CONTENT[contid]["title"]
        else:
            return "Access Denied"
    except KeyError:
        return "Content not found"

