        raise ValueError(f"Hash algorithm {algorithm} is not available")
    safe_hashes = ["sha256", "sha512", "sha244", "sha384", "blake2s"]
    if algorithm not in safe_hashes:
        raise ValueError(f"Hash algorithm {algorithm} is not available")
    hasher = hmac.new(secret, content, algorithm)
