def generate_client_receipt(order_id, template):
    if order_id not in transactions:
        raise ValueError("Order not found")
    transaction = transactions[order_id]
    class SecureTransaction:
        def __init__(self, transaction):
            self._transaction = transaction

        def __getattr__(self, name):
            if name == 'customer':
                return SecureClient(self._transaction.customer)
            return getattr(self._transaction, name)

    class SecureClient:
        def __init__(self, customer):
            self._customer = customer

        def __getattr__(self, name):
            if name in ['address', 'credit_card']:
                raise ValueError(f"Access to {name} is not allowed in receipts")
            return getattr(self._customer, name)

    secure_transaction = SecureTransaction(transaction)
    return template.format(order=secure_transaction, customer=secure_transaction.customer)

