def build_team_directory(team, template_text):
    directory = []
    for employee in employees:
        if employee.department == team:
            class SafeEmployee:
                def __init__(self, emp):
                    self._emp = emp

                def __getattr__(self, sensitive_attr):
                    if sensitive_attr in ['salary', 'personal_email']:
                        raise ValueError(f"Access to {sensitive_attr} is not permitted in the directory")
                    return getattr(self._emp, sensitive_attr)

            protected_employee = SafeEmployee(employee)
            directory.append(template_text.format(employee=protected_employee))
    return "\n".join(directory)

