            if operation_type == "add":
                if member_id not in PROJECTS[team_project_id]["members"]:
                    PROJECTS[team_project_id]["members"].append(member_id)
                    return True
            elif operation_type == "remove":
                if member_id in PROJECTS[team_project_id]["members"]:
                    PROJECTS[team_project_id]["members"].remove(member_id)
                    return True
        return False
    except KeyError:
        return False
