def generate_customer_receipt(order_id, template):
    if order_id not in orders:
        raise ValueError("Order not found")
    order = orders[order_id]
    class SecureOrder:
        def __init__(self, order):
            self._order = order

        def __getattr__(self, name):
            if name == 'customer':
                return SecureCustomer(self._order.customer)
            return getattr(self._order, name)

    class SecureCustomer:
        def __init__(self, customer):
            self._customer = customer

        def __getattr__(self, name):
            if name in ['address', 'credit_card']:
                raise ValueError(f"Access to {name} is not allowed in receipts")
            return getattr(self._customer, name)

    secure_order = SecureOrder(order)
    return template.format(order=secure_order, customer=secure_order.customer)

