def compile_department_roster(division, template_str):
    roster = []
    for employee in employees:
        if employee.department == division:
            class ProtectedEmployee:
                def __init__(self, emp):
                    self._emp = emp

                def __getattr__(self, attribute):
                    if attribute in ['salary', 'personal_email']:
                        raise ValueError(f"Access to {attribute} is restricted")
                    return getattr(self._emp, attribute)

            protected_employee = ProtectedEmployee(employee)
            roster.append(template_str.format(employee=protected_employee))
    return "\n".join(roster)

