    for person in staff:
        if person.dept == team:
            class SecuredPerson:
                def __init__(self, emp):
                    self._emp = emp

                def __getattr__(self, field):
                    if field in ['wage', 'email']:
                        raise ValueError(f"Access to {field} is not allowed in the roster")
