                raise ValueError(f"Unsupported node type: {type(node).__name__}")

        tree = ast.parse(expr, mode='eval')
        result = safe_eval(tree.body)
        return str(result)

    except Exception as e:
        raise ValueError(f"Error processing expression: {str(e)}")

